INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28601, '1 Timothy 3:3', '1 Timothy', 3, 3, '&nbsp;چې نۀ شرابى، نۀ جګړه مار، بلکې نرم مزاجه وى او نۀ بحث کوونکے او نۀ د پېسو لالچى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28602, '1 Timothy 3:4', '1 Timothy', 3, 4, '&nbsp;په کار ده چې هغه خپل خاندان په ښۀ طريقه وساتى او د خپلو بچو ښۀ تربيت وکړى چې د هغۀ احترام او فرمانبردارى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28603, '1 Timothy 3:5', '1 Timothy', 3, 5, '&nbsp;ځکه کۀ چرې يو سړے د خپل کور په بندوبست کولو نۀ پوهيږى نو هغه به د خُدائ پاک د جماعت ساتنه څنګه وکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28604, '1 Timothy 3:6', '1 Timothy', 3, 6, '&nbsp;په کار دے چې هغه دې نوے ايماندار نۀ وى، هسې نه چې هغه مغروره شى او خُدائ پاک يې مجرم وګرځوى لکه څنګه چې يې اِبليس ګرځولے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28605, '1 Timothy 3:7', '1 Timothy', 3, 7, '&nbsp;او د دې نه علاوه په کار دى چې هغه د جماعت نه بهر په خلقو کښې نېکنامه وى، او بدنامه نۀ وى نو چې د اِبليس په جال کښې راګېر نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28606, '1 Timothy 3:8', '1 Timothy', 3, 8, '&nbsp;خادِمان دې هم دغه شان ادب ناک وى، دوه ژبې يا شرابى يا د ناجائزه مال دولت لالچيان دې نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28607, '1 Timothy 3:9', '1 Timothy', 3, 9, '&nbsp;او په کار دى چې هغوئ د ايمان راز په صفا زړۀ قائم وساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28608, '1 Timothy 3:10', '1 Timothy', 3, 10, '&nbsp;او هغوئ دې اول وآزمائيلے شى، کۀ چرې هغوئ بې‌اِلزامه ثابت شى نو د خِدمت کار ته يې پرېږدئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28609, '1 Timothy 3:11', '1 Timothy', 3, 11, '&nbsp;ښځې دې هم دغه شان ادب ناکې وى، غېبت کوونکې دې نۀ وى بلکې پرهيزګارې او په ټولو خبرو کښې دې ايماندارې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28610, '1 Timothy 3:12', '1 Timothy', 3, 12, '&nbsp;خادِم دې تش د يوې ښځې خاوند وى، او هغوئ دې د خپلو بچو او د خپل خاندان په ښۀ طريقې سره بندوبست کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28611, '1 Timothy 3:13', '1 Timothy', 3, 13, '&nbsp;ځکه چې کوم خادِمان چې د خِدمت کار په ښۀ شان کوى، هغوئ به عزتمند وګڼلے شى او په هغه ايمان کښې چې په عيسىٰ مسيح باندې دے ډېره زړۀ ورتيا ومومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28612, '1 Timothy 3:14', '1 Timothy', 3, 14, '&nbsp;زۀ اُميد کوم چې تاسو له زر درشم، خو زۀ بيا هم تاسو ته دا هدايات ليکم چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28613, '1 Timothy 3:15', '1 Timothy', 3, 15, '&nbsp;کۀ زما په درتلو کښې ډيل وشى نو چې تاسو خبر يئ چې د خُدائ پاک په کور کښې مونږ له څنګه سلوک په کار دے، يعنې د ژوندى خُدائ پاک په جماعت کښې کوم چې د حق ستن او بنياد دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28614, '1 Timothy 3:16', '1 Timothy', 3, 16, '&nbsp;په دې کښې هيڅ شک نشته چې د ايمان راز لوئ دے، يعنې هغه د انسان په بدن کښې راښکاره شو، او د روح په وسيله رښتونے ثابت شو او فرښتو هغه وليدو، او په غېر قومونو کښې د هغۀ پېغام خور شو، او په ټولې دُنيا کښې خلقو په هغۀ ايمان راوړو، او په جلال کښې بره پورته کړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28615, '1 Timothy 4:1', '1 Timothy', 4, 1, '&nbsp;نو روحُ القُدس صفا وائى چې په آخرو زمانو کښې به ځينې خلق د بې‌لارې کوونکو روحونو او شېطانى تعليمونو طرف ته توجو شى او د ايمان نه به واوړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28616, '1 Timothy 4:2', '1 Timothy', 4, 2, '&nbsp;دا به د هغه دروغژنو خلقو د رياکارۍ په سبب وى، د چا ضمير چې مړ شوے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28617, '1 Timothy 4:3', '1 Timothy', 4, 3, '&nbsp;هغوئ به خلق د وادۀ کولو نه منع کوى، او هغوئ به خلق د ځينې هغه خوراکونو نه منع کوى چې خُدائ پاک د دې دپاره پېدا کړى دى چې ايمان راوړونکى او حق پېژندونکى دې په شُکر ګزارۍ سره خورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28618, '1 Timothy 4:4', '1 Timothy', 4, 4, '&nbsp;ځکه هر څۀ چې خُدائ پاک پېدا کړى دى هغه ښۀ دى او د څۀ نه هم اِنکار کول نۀ دى په کار، او څۀ چې ملاويږى په شُکر ګزارۍ سره يې خورئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28619, '1 Timothy 4:5', '1 Timothy', 4, 5, '&nbsp;ځکه چې دا د خُدائ پاک په کلام او د دُعا په وسيله پاک شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28620, '1 Timothy 4:6', '1 Timothy', 4, 6, '&nbsp;کۀ چرې تۀ دا هدايات د وروڼو او خوېندو په وړاندې پېش کړې نو تۀ به د عيسىٰ مسيح هغه ښۀ خادِم يې څوک چې د ايمان په خبرو او نېک تعليم پائى او عمل پرې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28621, '1 Timothy 4:7', '1 Timothy', 4, 7, '&nbsp;د بې‌دينۍ د بحث او د زړو ښځو د قيصو نه ځان ساته او د دې په ځائ خپل ځان ته د ديندارۍ تربيت ورکوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28622, '1 Timothy 4:8', '1 Timothy', 4, 8, '&nbsp;ځکه چې د جسمانى تربيت فائده شته خو د ديندارۍ تربيت حاصلول د دې نه ښۀ دى ځکه چې په اوسنى او راتلونکى ژوندون کښې به د دې دواړو فائده وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28623, '1 Timothy 4:9', '1 Timothy', 4, 9, '&nbsp;دا خبره رښتيا ده او په پوره شان د قبلولو وړ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28624, '1 Timothy 4:10', '1 Timothy', 4, 10, '&nbsp;مونږ محنت او خوارى ځکه کوُو چې زمونږ اُميد په هغه ژوندى خُدائ پاک دے څوک چې د ټولو خلقو او خاص د ايمان راوړونکو خلاصونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28625, '1 Timothy 4:11', '1 Timothy', 4, 11, '&nbsp;د دې خبرو تاکيد کوه او تعليم يې ورکوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28626, '1 Timothy 4:12', '1 Timothy', 4, 12, '&nbsp;هيڅوک دې ستا ځوانۍ ته سپک ونۀ ګورى، بلکې تۀ د ايماندارانو دپاره په خبرو کولو، چال چلن، مينه، ايمان او پاکۍ کښې نمونه جوړ شه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28627, '1 Timothy 4:13', '1 Timothy', 4, 13, '&nbsp;ترڅو چې زۀ نۀ يم راغلے، نو د خلقو په مينځ کښې د کلام په تلاوت او نصيحت کولو او تعليم ورکولو کښې بوخت اوسه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28628, '1 Timothy 4:14', '1 Timothy', 4, 14, '&nbsp;د هغه روحانى نعمت نه مۀ بې‌غوره کېږه چې تا ته د پېشګويۍ په وسيله د جماعت د مشرانو د لاس اېښودلو په وخت درکړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28629, '1 Timothy 4:15', '1 Timothy', 4, 15, '&nbsp;په دې خبرو عمل کوه او خپل ځان په دې کښې مشغول کړه چې ستا ترقى ټولو ته ښکاره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28630, '1 Timothy 4:16', '1 Timothy', 4, 16, '&nbsp;د خپل ځان او د خپل تعليم ډېر خيال کوه او پرې قائم پاتې شه ځکه چې په داسې کولو به تۀ د خپل ځان او د خپلو اورېدونکو د خلاصون سبب شې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28631, '1 Timothy 5:1', '1 Timothy', 5, 1, '&nbsp;مشر سړى ته سختې خبرې مۀ کوه بلکې هغۀ ته خواست کوه او د خپل پلار په شان خبرې ورسره کوه او ځوانانو سره د وروڼو په شان سلوک کوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28632, '1 Timothy 5:2', '1 Timothy', 5, 2, '&nbsp;او زړې ښځې د ميندو په شان ګڼه او ځوانې ښځې په پوره پاکۍ سره خوېندې ګڼه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28633, '1 Timothy 5:3', '1 Timothy', 5, 3, '&nbsp;د کونډو عزت کوه څوک چې واقعى ضرورتمندې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28634, '1 Timothy 5:4', '1 Timothy', 5, 4, '&nbsp;کۀ د کونډې بچى يا نمسى وى نو هغوئ دې د ټولو نه اول د خپل خاندان ذمه وارى وپېژنى کومه چې د هغوئ مذهبى فريضه هم ده، او هغوئ دې داسې د خپل مور پلار او نيکونو حق ادا کړى ځکه چې داسې کول د خُدائ پاک خوښ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28635, '1 Timothy 5:5', '1 Timothy', 5, 5, '&nbsp;کومه کونډه چې واقعى يواځې وى او د هغې هيڅوک هم نۀ وى، هغه په خُدائ پاک اُميد ساتى او شپه ورځ به په زارۍ او دُعا کښې آخته وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28636, '1 Timothy 5:6', '1 Timothy', 5, 6, '&nbsp;خو کومه کونډه چې په عېش عشرت آخته ده، نو هغه په ژوندانۀ مړه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28637, '1 Timothy 5:7', '1 Timothy', 5, 7, '&nbsp;د دې خبرو نصيحت هم ورته وکړه چې هغوئ د اِلزام نه بچ پاتې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28638, '1 Timothy 5:8', '1 Timothy', 5, 8, '&nbsp;او کۀ څوک د خپلوانو او خاص د خپل خاندان د خلقو خيال نۀ ساتى نو هغه د ايمان نه منکر او د بې‌ايمانه نه هم بدتر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28639, '1 Timothy 5:9', '1 Timothy', 5, 9, '&nbsp;هغه کونډه دې د امداد په فهرست کښې وليکلے شى کومه چې د شپېتو کالو نه کمه نۀ وى او چې يو ځل وادۀ شوې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28640, '1 Timothy 5:10', '1 Timothy', 5, 10, '&nbsp;په کار ده چې هغه په خپلو نېکو کارونو کښې مشهوره وى، خپل بچى يې رالوئ کړى وى، د مسافرو مېلمستيا يې کړې وى، د مقدسينو پښې يې وينځلې وى، د مصيبت ځپلو مدد يې کړے وى او چې خپل ځان يې د هر ښۀ کار کولو دپاره وقف کړے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28641, '1 Timothy 5:11', '1 Timothy', 5, 11, '&nbsp;خو د ځوانو کونډو نومونه په فهرست کښې مۀ ليکئ ځکه کله چې د هغوئ شهوت هغوئ د مسيح نه لرى کړى نو هغوئ بيا د وادۀ خواهش کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28642, '1 Timothy 5:12', '1 Timothy', 5, 12, '&nbsp;او په دې وجه به هغوئ د سزا لائقې وګرځى ځکه چې په نِکاح کښې شوې هغوئ خپله اولنۍ وعده ماته کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28643, '1 Timothy 5:13', '1 Timothy', 5, 13, '&nbsp;او د دې نه علاوه هغوئ کور په کور ګرځى او بې‌کاره اوسېدل زده کوى، او نۀ صرف بې‌کاره ګرځى بلکې غېبت کوى او د نورو په کار کښې ګوتې وهى او هغه خبرې کوى چې ورته نۀ دى کول په کار.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28644, '1 Timothy 5:14', '1 Timothy', 5, 14, '&nbsp;نو زما نصيحت دا دے چې ځوانې کونډې دې وادۀ وکړى هغوئ دې بچى پېدا کړى او د کور اِنتظام دې سمبال کړى او مخالفينو له دې د بدې وينا کولو موقع ورنۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28645, '1 Timothy 5:15', '1 Timothy', 5, 15, '&nbsp;ځکه چې څۀ کونډې ګمراه شوې او د شېطان په لاره روانې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28646, '1 Timothy 5:16', '1 Timothy', 5, 16, '&nbsp;کۀ د يوې ايماندارې ښځې په رشته‌دارو کښې نورې غريبې کونډې وى نو هغه دې په خپله د هغوئ مدد کوى او په جماعت دې بوج نۀ اچوى، نو داسې به جماعت د هغه ضرورتمندو کونډو څوک چې په رښتيا حقدارې دى مدد وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28647, '1 Timothy 5:17', '1 Timothy', 5, 17, '&nbsp;هغه مشران چې د جماعت ښۀ اِنتظام کوى، او خاص هغوئ چې په کلام اورولو او په تعليم ورکولو کښې خوارى کوى، هغوئ دې يو په دوه د عزت لائق وګڼلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28648, '1 Timothy 5:18', '1 Timothy', 5, 18, '&nbsp;ځکه چې د خُدائ پاک کلام فرمائى چې، ”تاسو د غوبل په وخت کښې د غوَيى خولې ته کوَرے مۀ اچوئ،“ او بل ځائ فرمائى، ”مزدور د خپلې مزدورۍ حقدار دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28649, '1 Timothy 5:19', '1 Timothy', 5, 19, '&nbsp;کوم اِلزام چې د يو مشر په خِلاف وشى نو هغه د دوو يا د درېو ګواهانو د ګواهۍ نه بغېر مۀ منه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28650, '1 Timothy 5:20', '1 Timothy', 5, 20, '&nbsp;څوک چې ګناه کوى، هغوئ د ټول جماعت په وړاندې ملامت کړئ د دې دپاره چې نور خلق هم وۀ يريږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28651, '1 Timothy 5:21', '1 Timothy', 5, 21, '&nbsp;زۀ د خُدائ پاک او د عيسىٰ مسيح او د غوره شوو فرښتو په مخکښې تا له حُکم درکوم او تاکيد کوم چې په دې هداياتو بغېر د تعصب نه عمل کوه او د هيچا طرفدارى مۀ کوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28652, '1 Timothy 5:22', '1 Timothy', 5, 22, '&nbsp;په چا زر لاس مۀ کېږده چې د خُدائ پاک د خِدمت دپاره مخصوص شى، او د نورو په ګناهونو کښې مۀ شريک کېږه. خپل ځان پاک وساته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28653, '1 Timothy 5:23', '1 Timothy', 5, 23, '&nbsp;صرف اوبۀ مۀ څښه بلکې د خپلې معدې او اکثر د ناجوړه کېدو په وجه لږ شان مے هم استعمالوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28654, '1 Timothy 5:24', '1 Timothy', 5, 24, '&nbsp;د څۀ کسانو ګناهونه ښکاره وى او هغوئ عدالت ته پېش کړى، خو د ځينو ګناهونه به وروستو ښکاره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28655, '1 Timothy 5:25', '1 Timothy', 5, 25, '&nbsp;دغه شان د ځينې خلقو ښۀ کارونه هم ليدلے کيږى، خو کوم ښۀ کارونه چې په پټه شوى وى، نو هغه به هم يوه ورځ ښکاره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28656, '1 Timothy 6:1', '1 Timothy', 6, 1, '&nbsp;هغوئ ټول چې د غلامۍ د جغ د لاندې دى، هغوئ دې خپل مالِکان پوره د عزت لائق وګڼى چې د خُدائ پاک نوم او زمونږ تعليم بدنام نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28657, '1 Timothy 6:2', '1 Timothy', 6, 2, '&nbsp;خو هغه غلامان چې مالِکان يې ايمانداران وى، هغوئ دې خپل مالِکان د ورورولۍ په سبب سپک نۀ ګڼى، بلکې نور زيات خِدمت دې هم کوى، ځکه څوک چې د دوئ د ښۀ خدمت نه فائده اخلى هغه ايمانداران او د مينې قابل دى. بيا تۀ د دې خبرو تعليم او ډاډ ورکوه چې د هغوئ ښۀ تابعدارى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28658, '1 Timothy 6:3', '1 Timothy', 6, 3, '&nbsp;کۀ څوک غلط تعليم ورکوى او زمونږ د مالِک عيسىٰ مسيح خبرې او د هغۀ هغه تعليم نۀ منى کوم چې د ديندارۍ په مطابق دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28659, '1 Timothy 6:4', '1 Timothy', 6, 4, '&nbsp;هغه مغرور دے او په هيڅ نۀ پوهيږى، او هغۀ ته د بحث مباحثى او زبانى تکرار بيمارى ده او د دې په وجه کينه او جګړې او بده وينا او بدګُمانى رامينځ ته کيږى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28660, '1 Timothy 6:5', '1 Timothy', 6, 5, '&nbsp;او د هغوئ په مينځ کښې مدام بحث پېدا کيږى د چا عقل چې خراب شوے دے، او د حق نه محروم دى او هغوئ ديندارى تش د ګټې ذريعه ګڼى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28661, '1 Timothy 6:6', '1 Timothy', 6, 6, '&nbsp;يقيناً چې د قناعت سره ديندارۍ کښې لويه ګټه ده،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28662, '1 Timothy 6:7', '1 Timothy', 6, 7, '&nbsp;ځکه چې نۀ خو مونږ دُنيا ته څۀ راوړى دى او نۀ مونږ د دې نه څۀ وړلے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28663, '1 Timothy 6:8', '1 Timothy', 6, 8, '&nbsp;خو کۀ مونږ سره خوراک او جامې وى نو مونږ دې په هغې خوشحاله يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28664, '1 Timothy 6:9', '1 Timothy', 6, 9, '&nbsp;خو څوک چې مالداره کېدل غواړى نو هغوئ په آزمېښتونو او د ډېرو نورو عبثو نقصانى خواهشونو په دام کښې راګېر شى کوم چې خلق د تباهۍ او هلاکت په درياب کښې غرقوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28665, '1 Timothy 6:10', '1 Timothy', 6, 10, '&nbsp;ځکه چې د پېسو مينه د هر قِسم بدۍ بېخ دے، او د مالداره کېدو په لالچ کښې څۀ خلق د ايمان نه ګمراه شول او خپل ځانونه يې په قِسما قِسم غمونو غلبيل کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28666, '1 Timothy 6:11', '1 Timothy', 6, 11, '&nbsp;خو اے د خُدائ پاک بنده، تۀ د دې ټولو خبرو نه ځان وساته او د صداقت، ديندارۍ، ايمان، مينې، صبر او په نرم طبيعت پسې کوشش کوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28667, '1 Timothy 6:12', '1 Timothy', 6, 12, '&nbsp;د ايمان په جنګ کښې ښۀ وجنګېږه، او په هغه ابدى ژوندون قبضه وکړه د کوم دپاره چې تۀ رابللے شوے يې او د کوم چې تا د ډېرو ګواهانو په وړاندې ډاډه اقرار کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28668, '1 Timothy 6:13', '1 Timothy', 6, 13, '&nbsp;زۀ تاسو ته حُکم درکوم د هغه خُدائ پاک په وړاندې چې ټولو څيزونو له ژوند ورکوى، او د عيسىٰ مسيح په وړاندې چا چې د پنطوس پيلاطوس په مخکښې ډاډه اقرار کړے وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28669, '1 Timothy 6:14', '1 Timothy', 6, 14, '&nbsp;او تۀ زمونږ د مالِک عيسىٰ مسيح د ظاهرېدو تر ورځې پورې دا حُکم بې‌داغه او بې‌اِلزامه وساته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28670, '1 Timothy 6:15', '1 Timothy', 6, 15, '&nbsp;نو خُدائ پاک به هغه په مناسب وخت را ښکاره کړى، او خُدائ پاک واحد، مبارک حکمران، د بادشاهانو بادشاه او د مالِکانو مالِک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28671, '1 Timothy 6:16', '1 Timothy', 6, 16, '&nbsp;دا واحد هغه دے چې څوک غېر فانى دے او هغه په هغه بې‌مثاله نُور کښې اوسيږى چې نۀ چا ليدلے او نۀ به يې ووينى. د هغۀ عزت او بادشاهى دې تل تر تله وى، آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28672, '1 Timothy 6:17', '1 Timothy', 6, 17, '&nbsp;او څوک چې د دې موجوده زمانې دولتمند دى هغوئ ته حُکم ورکړه چې مغرور کيږى دې نه، او نۀ دې په نا اعتباره مال څۀ اُميد کوى، بلکې په خُدائ پاک دې اُميد ساتى څوک چې د خوشحالۍ دپاره مونږ له ټول څيزونه ډېر زيات راکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28673, '1 Timothy 6:18', '1 Timothy', 6, 18, '&nbsp;هغوئ دې نېکى کوى او په ښو کارونو کښې دې مالداره شى، او سخاوت دې کوى او مدد کولو ته دې تيار اوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28674, '1 Timothy 6:19', '1 Timothy', 6, 19, '&nbsp;نو دغه شان به هغوئ ځان دپاره يوه داسې خزانه رايوځائ کړى چې په راروان وخت کښې به د هغوئ دپاره يو مضبوط بنياد وى او په هغې به هغوئ رښتينے ژوندون تر لاسه کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28675, '1 Timothy 6:20', '1 Timothy', 6, 20, '&nbsp;اے تيموتيوسه، د هغه څۀ حفاظت کوه کوم چې تا ته حواله شوے دے. او د هغه عبثو او فضولو خبرو نه لرې اوسه کوم ته چې تش په نامه عِلم وئيل کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28676, '1 Timothy 6:21', '1 Timothy', 6, 21, '&nbsp;د دې بحثونو په وجه څۀ کسان د ايمان نه واوړېدل. په تاسو ټولو دې د خُدائ پاک فضل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28677, '2 Timothy 1:1', '2 Timothy', 1, 1, '&nbsp;د پولوس د طرف نه چې د خُدائ پاک په مرضۍ د عيسىٰ مسيح رسول دے، او د دې دپاره چې په عيسىٰ مسيح کښې وعده شوے ژوند خلقو ته ورسوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28678, '2 Timothy 1:2', '2 Timothy', 1, 2, '&nbsp;زۀ خپل خوږ زوئ تيموتيوس ته دا خط ليکم. د خُدائ پلار او زمونږ د مالِک عيسىٰ مسيح فضل، رحم او سلامتى دې په تا وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28679, '2 Timothy 1:3', '2 Timothy', 1, 3, '&nbsp;زۀ د هغه خُدائ پاک شُکر کوم د چا عبادت چې زۀ په صفا زړۀ د خپل پلار نيکۀ په شان کوم، او زۀ هر وخت شپه او ورځ په خپلو دُعاګانو کښې تا يادوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28680, '2 Timothy 1:4', '2 Timothy', 1, 4, '&nbsp;کله چې زۀ ستا هغه د جدايۍ د وخت اوښکې رايادې کړم، نو تا سره د بيا ليدو خواهشمند يم، د دې دپاره چې د خوشحالۍ نه ډک شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28681, '2 Timothy 1:5', '2 Timothy', 1, 5, '&nbsp;ما ته ستا د مينې نه هغه ډک ايمان راياديږى کوم چې اول ستا د نيا لوئيس او ستا د مور يونيکې وو، او اوس زما يقين دے چې ستا هم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28682, '2 Timothy 1:6', '2 Timothy', 1, 6, '&nbsp;په دې وجه زۀ تا ته دا خبره دريادوم چې تۀ د خُدائ پاک د هغه نعمت اور ته پوکے ورکړه کوم چې زما د لاس د کېښودلو په وسيله تا ته حاصل دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28683, '2 Timothy 1:7', '2 Timothy', 1, 7, '&nbsp;ځکه چې خُدائ پاک مونږ له بُزدله زړۀ نۀ دے راکړے بلکې راله يې زړَورتوب، مينه او په ځان د قابو ساتلو قدرت راکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28684, '2 Timothy 1:8', '2 Timothy', 1, 8, '&nbsp;نو بيا زمونږ د مالِک په حقله د ګواهۍ ورکولو يا زما نه چې د هغۀ قېدى يم، مۀ شرمېږه، بلکې د خُدائ پاک د قدرت په وسيله د زيرى د خاطره ما سره په تکليفونو کښې شريک شه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28685, '2 Timothy 1:9', '2 Timothy', 1, 9, '&nbsp;خُدائ پاک مونږ له خلاصون راکړو او مونږ يې خپل مقدس ژوند ته راوبللو. هغۀ دا زمونږ د نېکو کارونو په خاطر ونۀ کړو، بلکې دا د اول نه زمونږ دپاره د هغۀ منصوبه وه، يعنې د ازل نه، چې د عيسىٰ مسيح په وسيله په مونږ خپل فضل وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28686, '2 Timothy 1:10', '2 Timothy', 1, 10, '&nbsp;خو اوس دا زمونږ د خلاصوونکى عيسىٰ مسيح په راتلو سره ښکاره شو چا چې مرګ نشت کړو، او هغه ژوند يې شتۀ کړو او غېر فانى ژوندون يې د زيرى په وسيله څرګند کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28687, '2 Timothy 1:11', '2 Timothy', 1, 11, '&nbsp;د دې زېرى د بيانولو دپاره زۀ رسول او اُستاذ مقرر شوم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28688, '2 Timothy 1:12', '2 Timothy', 1, 12, '&nbsp;او هم په دې وجه زۀ دا تکليفونه زغمم. خو زۀ نۀ شرمېږم، ځکه په چا چې ما ايمان راوړے دے زۀ هغه پېژنم، او زما يقين دے چې څۀ چې ما هغۀ ته سپارلى دى د خپلو راتلو تر ورځې پورې هغه د هغې د حفاظت کولو قابل دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28689, '2 Timothy 1:13', '2 Timothy', 1, 13, '&nbsp;هغه معيارى تعليم چې تا زما نه په عيسىٰ مسيح کښې د ايمان او مينې په وسيله واورېدو په هغې معيار ژوند تېروه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28690, '2 Timothy 1:14', '2 Timothy', 1, 14, '&nbsp;د هغه روحُ القُدس په وسيله چې په مونږ کښې اوسيږى د هغه قيمتى خزانې حفاظت وکړه چې تا ته سپارلے شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28691, '2 Timothy 1:15', '2 Timothy', 1, 15, '&nbsp;څنګه چې تاسو ته پته ده چې د آسيه صوبې ټول خلق سره د فوګلوسه او هرموګينيسه زما نه منکر شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28692, '2 Timothy 1:16', '2 Timothy', 1, 16, '&nbsp;مالِک دې د اُنيسفرس په خاندان رحم وکړى ځکه چې زۀ اکثر هغوئ په هر لحاظ تازه کړے يم، او زما د زولنو نه ونۀ شرمېدو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28693, '2 Timothy 1:17', '2 Timothy', 1, 17, '&nbsp;خو کله چې هغه روم ته راغلو نو ډېر په ليوالتيا يې زما لټون وکړو او زۀ يې وموندلم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28694, '2 Timothy 1:18', '2 Timothy', 1, 18, '&nbsp;مالِک دې په هغه لويه ورځ په هغۀ رحم وکړى، او تۀ ښۀ خبر يې چې په اِفِسوس کښې هغۀ څومره ډېر خِدمت وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28695, '2 Timothy 2:1', '2 Timothy', 2, 1, '&nbsp;نو اے زما زويه، نو بيا تۀ په هغه فضل مضبوط شه چې په عيسىٰ مسيح کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28696, '2 Timothy 2:2', '2 Timothy', 2, 2, '&nbsp;او کومې خبرې چې تا د ډېرو ګواهانو په موجودګۍ کښې زما نه اورېدلى دى هغه داسې وفادارو کسانو ته په حواله کړه څوک چې نورو ته د تعليم ورکولو لائق وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28697, '2 Timothy 2:3', '2 Timothy', 2, 3, '&nbsp;د عيسىٰ مسيح د يو ښۀ سپاهى په شان ما سره په سختو زغملو کښې شريک شه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28698, '2 Timothy 2:4', '2 Timothy', 2, 4, '&nbsp;يو فوجى خپل ځان په روزمره معاملو کښې نۀ راګېروى ځکه چې د هغۀ مقصد د خپل آفسر زړۀ ساتل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28699, '2 Timothy 2:5', '2 Timothy', 2, 5, '&nbsp;او د لوبغاړى په صورت کښې هم تر هغې چا ته انعام نۀ ورکولے کيږى ترڅو چې يې په قانونى توګه مقابله نۀ وى کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28700, '2 Timothy 2:6', '2 Timothy', 2, 6, '&nbsp;کوم زميندار چې محنت کوى نو په کار دے چې د فصل وړومبۍ حِصه هغۀ ته ورکړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');